/**
 * Applies the SQL migrations in ./migrations (generated by drizzle-kit).
 * Works for both PGlite and node-postgres via the dialect-specific migrator.
 *
 * Run directly: `pnpm db:migrate`
 */
import path from "node:path";
import type { Db } from "./client";

const migrationsFolder = path.join(process.cwd(), "lib", "db", "migrations");

export async function runMigrations(db: Db) {
  if (process.env.DATABASE_URL) {
    const { migrate } = await import("drizzle-orm/node-postgres/migrator");
    await migrate(db as never, { migrationsFolder });
  } else {
    const { migrate } = await import("drizzle-orm/pglite/migrator");
    await migrate(db as never, { migrationsFolder });
  }
}

if (process.argv[1] && process.argv[1].endsWith("migrate.ts")) {
  (async () => {
    const { getDb } = await import("./client");
    await getDb(); // getDb runs migrations for PGlite; for Postgres run explicitly:
    if (process.env.DATABASE_URL) await runMigrations(await getDb());
    console.log("migrations applied");
    process.exit(0);
  })().catch((e) => {
    console.error(e);
    process.exit(1);
  });
}
